package com.hostelhub.controller;
import com.hostelhub.model.*; import com.hostelhub.repository.*; import com.hostelhub.service.RealtimeEventService; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import java.util.*;
@RestController @RequestMapping("/api/rooms") public class RoomController{ private final RoomRepository repo; private final StudentRepository students; private final RealtimeEventService events; public RoomController(RoomRepository r,StudentRepository s,RealtimeEventService e){repo=r;students=s;events=e;} @GetMapping public List<Room> all(){return repo.findAll();} @PostMapping public Room add(@Valid @RequestBody Room r){updateStatus(r);return repo.save(r);} @PostMapping("/{id}/allocate/{studentId}") public Student allocate(@PathVariable Long id,@PathVariable Long studentId){Room r=repo.findById(id).orElseThrow();Student s=students.findById(studentId).orElseThrow();if(r.getOccupied()>=r.getCapacity())throw new IllegalStateException("Room is full");if(s.getRoomId()!=null)throw new IllegalStateException("Student already has a room");s.setRoomId(r.getId());s.setRoomNumber(r.getRoomNumber());students.save(s);r.setOccupied(r.getOccupied()+1);updateStatus(r);repo.save(r);events.publish("room",s.getName()+" allocated to room "+r.getRoomNumber());return s;} @PostMapping("/{id}/deallocate/{studentId}") public Student deallocate(@PathVariable Long id,@PathVariable Long studentId){Room r=repo.findById(id).orElseThrow();Student s=students.findById(studentId).orElseThrow();if(!Objects.equals(s.getRoomId(),r.getId()))throw new IllegalStateException("Student is not allocated to this room");s.setRoomId(null);s.setRoomNumber(null);students.save(s);r.setOccupied(Math.max(0,r.getOccupied()-1));updateStatus(r);repo.save(r);events.publish("room",s.getName()+" deallocated from room "+r.getRoomNumber());return s;} private void updateStatus(Room r){r.setStatus(r.getOccupied()>=r.getCapacity()?"FULL":"AVAILABLE");}}
